#!/bin/bash
set -e

echo "=== Aggiorno le copertine definitive (con banner app integrato) ==="

mkdir -p public/covers

base64 -d > public/covers/feeder.jpg << 'FEEDEREOF'

FEEDEREOF

base64 -d > public/covers/mare-e-foce.jpg << 'MAREEOF'

MAREEOF

echo "=== Copertine aggiornate: ==="
echo "  public/covers/feeder.jpg"
echo "  public/covers/mare-e-foce.jpg"
echo ""
echo "Ricorda: bash copertine-definitive.sh, poi:"
echo "git add -A && git commit -m 'aggiorna copertine definitive con banner app integrato' && git push"
